// BACKTRACKING TEMPLATE
// The three-step pattern: choose -> explore -> unchoose

function backtrack(candidates, path, result, start, /* other state */) {
    // BASE CASE: complete solution or invalid path
    if (/* solution complete */) {
        result.push([...path]); // copy path: arrays are references!
        return;
    }

    for (let i = start; i < candidates.length; i++) {
        // PRUNING: skip if this candidate cannot lead to a solution
        if (/* pruning condition */) continue;

        // CHOOSE: add candidate to path
        path.push(candidates[i]);

        // EXPLORE: recurse with updated state
        backtrack(candidates, path, result, i + 1 /* or i */, /* updated state */);

        // UNCHOOSE: remove candidate from path (backtrack)
        path.pop();
    }
}

// WHY [...path] NOT path in result.push:
// path is a reference to a mutable array
// After backtracking, path will be modified by subsequent calls
// result.push(path) would store a reference that ends up empty
// result.push([...path]) creates an independent copy at this moment

// BACKTRACKING vs DP vs DFS:
// DFS (graphs/trees): visit each node once, O(V+E)
// Backtracking: visit each node potentially many times, builds solutions
// DP: overlapping subproblems, cache results
// Backtracking is used when:
//   - All solutions needed (not just optimal)
//   - No overlapping subproblems (or too expensive to cache)
//   - Constraint satisfaction (pruning makes it practical)

// COMPLEXITY:
// Subsets: O(n * 2^n) — 2^n subsets, each takes O(n) to copy
// Permutations: O(n * n!) — n! permutations, each takes O(n) to copy
// Combination Sum: O(n * 2^t/m) where t=target, m=min coin — exponential
// Pruning can dramatically reduce practical runtime even with exponential bounds

