// SUBSETS I (#78) — all subsets of unique array
function subsets(nums) {
    const result = [];
    function backtrack(start, path) {
        result.push([...path]); // add subset at EVERY node (including empty)
        for (let i = start; i < nums.length; i++) {
            path.push(nums[i]);          // choose
            backtrack(i + 1, path);      // explore (i+1: no duplicates, forward only)
            path.pop();                  // unchoose
        }
    }
    backtrack(0, []);
    return result;
}
// nums=[1,2,3]: subsets=[[], [1], [1,2], [1,2,3], [1,3], [2], [2,3], [3]]
console.log(subsets([1,2,3])); // 8 subsets (2^3)

// SUBSETS II (#90) — duplicates in input, unique subsets in output
function subsetsWithDup(nums) {
    nums.sort((a, b) => a - b); // SORT FIRST: groups duplicates
    const result = [];
    function backtrack(start, path) {
        result.push([...path]);
        for (let i = start; i < nums.length; i++) {
            // SKIP DUPLICATES at the same level:
            // If nums[i] == nums[i-1] and i > start:
            //   nums[i-1] was already tried as the first choice at this level
            //   All subsets starting with nums[i-1] are already in result
            //   Trying nums[i] (same value) again would create duplicates
            if (i > start && nums[i] === nums[i-1]) continue;
            path.push(nums[i]);
            backtrack(i + 1, path);
            path.pop();
        }
    }
    backtrack(0, []);
    return result;
}
// nums=[1,2,2]: unique subsets: [],[1],[1,2],[1,2,2],[2],[2,2]
console.log(subsetsWithDup([1,2,2]));
// 6 subsets (not 8, because [1,2] would appear twice without deduplication)

// WHY i > start (not i > 0):
// nums=[2,2,2], start=0:
//   i=0: choose 2, recurse with start=1
//   i=1: nums[1]=2==nums[0]=2 BUT i=1 == start=0? NO, i=1 > start=0
//         SKIP: [2] subsets already covered by i=0
//   Result at depth 1: just [2] (not three copies of [2])
// If condition were i > 0:
//   At a deeper level with start=1, i=1: i=1 > 0 but i=1==start=1, so SKIP
//   This incorrectly skips the FIRST occurrence at this level
//   [2,2] would be skipped, missing a valid subset

