// PERMUTATIONS I (#46) — all orderings of unique array
function permute(nums) {
    const result = [];
    const used = new Array(nums.length).fill(false);

    function backtrack(path) {
        if (path.length === nums.length) {
            result.push([...path]);
            return;
        }
        for (let i = 0; i < nums.length; i++) {
            if (used[i]) continue; // skip: already in path
            used[i] = true;        // choose
            path.push(nums[i]);
            backtrack(path);        // explore
            path.pop();             // unchoose
            used[i] = false;
        }
    }
    backtrack([]);
    return result;
}
console.log(permute([1,2,3])); // 6 permutations

// PERMUTATIONS II (#47) — duplicates in input, unique permutations
function permuteUnique(nums) {
    nums.sort((a, b) => a - b); // sort to group duplicates
    const result = [];
    const used = new Array(nums.length).fill(false);

    function backtrack(path) {
        if (path.length === nums.length) {
            result.push([...path]);
            return;
        }
        for (let i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            // DEDUPLICATION for permutations:
            // Skip nums[i] if it equals nums[i-1] and nums[i-1] is NOT used
            // This means: we're in the branch where nums[i-1] hasn't been picked yet
            // at this level, so picking nums[i] now (identical value) would duplicate
            if (i > 0 && nums[i] === nums[i-1] && !used[i-1]) continue;
            used[i] = true;
            path.push(nums[i]);
            backtrack(path);
            path.pop();
            used[i] = false;
        }
    }
    backtrack([]);
    return result;
}
// nums=[1,1,2]: unique permutations: [1,1,2],[1,2,1],[2,1,1]
console.log(permuteUnique([1,1,2])); // 3 permutations (not 6)

// WHY !used[i-1] (not used[i-1]):
// Consider [1a, 1b, 2] where 1a and 1b are identical.
// We want to always pick 1a before 1b (canonical ordering).
// Skip picking 1b at position k if 1a is NOT yet in the path at positions 0..k-1
// !used[i-1] = 1a is not used = we haven't committed to having 1a before 1b
// So: if we are about to pick 1b without 1a being used, skip it.
// This enforces: 1a must always appear before 1b in any valid generation.

