// COMBINATION SUM I (#39) — reusable candidates
function combinationSum(candidates, target) {
    candidates.sort((a, b) => a - b); // sort for pruning
    const result = [];

    function backtrack(start, remaining, path) {
        if (remaining === 0) {
            result.push([...path]);
            return;
        }
        for (let i = start; i < candidates.length; i++) {
            if (candidates[i] > remaining) break; // PRUNING: sorted, so all further too large
            path.push(candidates[i]);
            backtrack(i, remaining - candidates[i], path); // i NOT i+1: reuse allowed
            path.pop();
        }
    }
    backtrack(0, target, []);
    return result;
}
console.log(combinationSum([2,3,6,7], 7));
// [[2,2,3],[7]]

// COMBINATION SUM II (#40) — one use each, duplicates in input
function combinationSum2(candidates, target) {
    candidates.sort((a, b) => a - b); // sort: groups duplicates AND enables pruning
    const result = [];

    function backtrack(start, remaining, path) {
        if (remaining === 0) {
            result.push([...path]);
            return;
        }
        for (let i = start; i < candidates.length; i++) {
            if (candidates[i] > remaining) break; // pruning
            // DEDUPLICATION: skip if same value as previous at this level
            if (i > start && candidates[i] === candidates[i-1]) continue;
            path.push(candidates[i]);
            backtrack(i + 1, remaining - candidates[i], path); // i+1: no reuse
            path.pop();
        }
    }
    backtrack(0, target, []);
    return result;
}
console.log(combinationSum2([10,1,2,7,6,1,5], 8));
// [[1,1,6],[1,2,5],[1,7],[2,6]]

// THE THREE KEY DIFFERENCES:
// Combination Sum I -> II:
// 1. Sort (both need it, but II needs it more for dedup)
// 2. Recurse with i -> i+1 (prevents reuse)
// 3. Add deduplication: if i > start && nums[i] == nums[i-1]: continue

// COMBINATION SUM III (#216 NeetCode150):
// Find all k-element combinations from 1-9 summing to n
function combinationSum3(k, n) {
    const result = [];
    function backtrack(start, remaining, path) {
        if (path.length === k && remaining === 0) { result.push([...path]); return; }
        if (path.length === k || remaining <= 0) return; // pruning
        for (let i = start; i <= 9; i++) {
            path.push(i);
            backtrack(i + 1, remaining - i, path);
            path.pop();
        }
    }
    backtrack(1, n, []);
    return result;
}
console.log(combinationSum3(3, 7)); // [[1,2,4]]

