// LETTER COMBINATIONS OF A PHONE NUMBER (#17)
// O(4^n * n) time, O(n) space (call stack depth)
function letterCombinations(digits) {
    if (!digits.length) return []; // edge case: empty input

    const phoneMap = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
        '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    };
    const result = [];

    function backtrack(index, path) {
        if (index === digits.length) {
            result.push(path.join('')); // or [...path] since path is array of chars
            return;
        }
        for (const letter of phoneMap[digits[index]]) {
            path.push(letter);                  // choose
            backtrack(index + 1, path);          // explore: advance to next digit
            path.pop();                          // unchoose
        }
    }
    backtrack(0, []);
    return result;
}

console.log(letterCombinations('23'));
// ['ad','ae','af','bd','be','bf','cd','ce','cf']
console.log(letterCombinations(''));   // []
console.log(letterCombinations('2'));  // ['a','b','c']

// ITERATIVE BFS ALTERNATIVE (not backtracking):
function letterCombinations_iter(digits) {
    if (!digits.length) return [];
    const phoneMap = {'2':'abc','3':'def','4':'ghi','5':'jkl',
                      '6':'mno','7':'pqrs','8':'tuv','9':'wxyz'};
    let result = [''];
    for (const digit of digits) {
        const letters = phoneMap[digit];
        const next = [];
        for (const combo of result) {
            for (const letter of letters) {
                next.push(combo + letter);
            }
        }
        result = next;
    }
    return result;
}
// Same output, O(4^n) space to store all intermediate combinations

// NOTE: The backtracking solution uses O(n) space (call stack + path)
// while the iterative solution uses O(4^n) space at peak
// For small n (phone numbers <= 10 digits) both are practical

