// PALINDROME PARTITIONING (#131)
// O(n * 2^n) time without precomputation, O(n^2 * 2^n) with n-len palindrome checks
function partition(s) {
    const result = [];

    // Palindrome check: O(n) per call
    function isPalin(str, l, r) {
        while (l < r) {
            if (str[l] !== str[r]) return false;
            l++; r--;
        }
        return true;
    }

    function backtrack(start, path) {
        if (start === s.length) {
            result.push([...path]); // complete partition
            return;
        }
        for (let end = start; end < s.length; end++) {
            if (isPalin(s, start, end)) {     // only recurse if palindrome
                path.push(s.slice(start, end + 1)); // add palindrome substring
                backtrack(end + 1, path);            // explore from end+1
                path.pop();                          // unchoose
            }
        }
    }
    backtrack(0, []);
    return result;
}

console.log(partition('aab'));
// [['a','a','b'], ['aa','b']]

// OPTIMISED: precompute palindrome table O(n^2) space and time
function partition_opt(s) {
    const n = s.length;
    // dp[i][j] = true if s[i..j] is a palindrome
    const dp = Array.from({length: n}, () => new Array(n).fill(false));
    // Fill by increasing length (same as Module 1 Lesson 6)
    for (let i = 0; i < n; i++) dp[i][i] = true; // single chars
    for (let i = 0; i < n-1; i++) dp[i][i+1] = s[i] === s[i+1]; // pairs
    for (let len = 3; len <= n; len++) {
        for (let i = 0; i <= n-len; i++) {
            const j = i + len - 1;
            dp[i][j] = s[i] === s[j] && dp[i+1][j-1];
        }
    }

    const result = [];
    function backtrack(start, path) {
        if (start === n) { result.push([...path]); return; }
        for (let end = start; end < n; end++) {
            if (dp[start][end]) {           // O(1) lookup
                path.push(s.slice(start, end + 1));
                backtrack(end + 1, path);
                path.pop();
            }
        }
    }
    backtrack(0, []);
    return result;
}
console.log(partition_opt('aab')); // same output

